const err = $json;
const execution = err.execution || {};
const lastNode = err.execution?.lastNodeExecuted || '';
const errMsg = err.execution?.error?.message || err.error?.message || '未知錯誤';
const errType = err.execution?.error?.name || err.error?.name || 'Error';
const wfId = err.workflow?.id || '';
const wfName = err.workflow?.name || '';
const execId = execution.id || '';

// 嚴重度判斷：含「critical / fatal / panic」字樣即視為 P0
const severity = /critical|fatal|panic|cannot connect/i.test(errMsg) ? 'P0' : 'P1';

return [{
  json: {
    workflow_id: wfId,
    workflow_name: wfName,
    node_name: lastNode,
    error_type: errType,
    error_message: errMsg.substring(0, 1000),
    execution_id: execId,
    severity,
    payload: err,
    occurred_at: new Date().toISOString()
  }
}];
